# ───────────────── target-shape resolution (one entry per type) ──────────────
#
# #727: this used to be an `if conn_type ==` chain in `services/run_target.py`, a
# second dispatch site outside this registry. Adding a datasource therefore meant
# editing that function TOO, quietly falsifying this module's "adding a datasource
# is one entry here" contract — the Iceberg addition (#716) already had to.
#
# The service layer keeps what is genuinely shared (targetless suites,
# orchestration-provider rejection, the HTTP error contract); only the SHAPE lives
# here, next to the adapter and runner for the same type.


def _require(target: dict[str, Any], field: str, conn_type: str) -> str:
    value = target.get(field)
    if not isinstance(value, str) or not value.strip():
        raise TargetShapeError(f"{conn_type} target requires a {field!r}")
    return value


def _opt(value: Any) -> str | None:
    return value if isinstance(value, str) and value.strip() else None


def _flatfile_target(target: dict[str, Any], conn_type: str) -> ResolvedTarget:
    # A batch target (regex `pattern`) resolves to a concrete path at run time; a literal target
    # carries `path`.
    if "pattern" in target and target.get("path"):
        raise TargetShapeError(
            "flat-file target is ambiguous: set either 'path' (literal) or "
            "'pattern' (batch), not both"
        )
    if "pattern" in target:
        return ResolvedTarget(table="", schema=None, catalog=None, batch=_batch_spec(target))
    return ResolvedTarget(table=_require(target, "path", conn_type), schema=None, catalog=None)


def _table_schema_target(target: dict[str, Any], conn_type: str) -> ResolvedTarget:
    """``table`` + optional ``schema`` — Snowflake and every generic SQL engine (#1678)."""
    return ResolvedTarget(
        table=_require(target, "table", conn_type),
        schema=_opt(target.get("schema")),
        catalog=None,
    )


def _generic_sql_target(spec: SqlEngineSpec) -> Callable[[dict[str, Any], str], ResolvedTarget]:
    """`_table_schema_target`, plus the engine's identifier rules checked at SAVE time (#1678):
    a name the run path can't address — or one PostgreSQL would silently truncate onto a
    different object — is a 422 on the suite, not an error on every run.
    """
    model = spec.config_model

    def _resolve(target: dict[str, Any], conn_type: str) -> ResolvedTarget:
        resolved = _table_schema_target(target, conn_type)
        for label, name in (("table", resolved.table), ("schema", resolved.schema)):
            problem = None if name is None else model.identifier_problem(name)
            if problem is not None:
                raise TargetShapeError(f"{conn_type} target {label} {problem}")
        return resolved

    return _resolve


def _unity_catalog_target(target: dict[str, Any], conn_type: str) -> ResolvedTarget:
    return ResolvedTarget(
        table=_require(target, "table", conn_type),
        schema=_opt(target.get("schema")),
        catalog=_require(target, "catalog", conn_type),
    )


def _iceberg_target(target: dict[str, Any], conn_type: str) -> ResolvedTarget:
    # Iceberg addresses a table by its ``namespace.table`` identifier (the namespace may itself be
    # multi-level, ``a.b``).
    table = _require(target, "table", conn_type)
    namespace = _opt(target.get("namespace"))
    return ResolvedTarget(
        table=f"{namespace}.{table}" if namespace else table, schema=None, catalog=None
    )


#: Flat-file batch selection strategies. Lives beside `_batch_spec` (#727) —
#: it is a property of the flat-file target shape, not of the service layer.
_BATCH_STRATEGIES = {"latest", "specific"}

#: A batch pattern is matched against every listed object key — for the run path
#: in the worker, for the preview in the API process (#1243). Python's `re` has
#: no match timeout, so a short length cap plus a shape check below are the only
#: defenses available; both apply here so save (`validate_target`) and preview
#: (`resolve_target`) enforce the identical rule.
_MAX_BATCH_PATTERN_LENGTH = 200

#: A quantifier token: `+`/`*`, or a `{m}`/`{m,}`/`{m,n}` bound — each optionally
#: lazy (`+?`, `{2,}?`, ...). `?` alone is excluded: it can't repeat a group's
#: match more than once, so it can't itself drive backtracking blowup.
_QUANTIFIER = r"(?:[+*]|\{\d+(?:,\d*)?\})\??"

#: Catastrophic backtracking's classic construct is a quantified GROUP whose own
#: body is itself quantified — e.g. ``(a+)+``, ``([a-z]*)+``, or the bounded
#: forms ``(a+){50,}``/``(a+){2,20}`` (still exponential — a bound just raises
#: the pathological-input length needed to blow up, it doesn't remove the
#: blowup). A pathological key (many repeats of the inner unit, then a
#: non-match) can drive any of these to exponential-time matching. Detected
#: structurally, not exhaustively: this catches the common shape, not every
#: possible ReDoS pattern.
_NESTED_QUANTIFIER_RE = re.compile(rf"\([^()]*{_QUANTIFIER}[^()]*\){_QUANTIFIER}")


def _reject_redos_shape(pattern: str) -> None:
        pattern=pattern,
        strategy=strategy,
        batch=batch if strategy == "specific" else None,
    )


