from backend.app.contracts import odcs

doc = {
    "apiVersion": "v3.2.0",
    "kind": "DataContract",
    "id": "orders-contract",
    "version": "1.0.0",
    "status": "active",
    "name": "Orders",
    "schema": [
        {
            "name": "orders",
            "physicalName": "ORDERS",
            "properties": [
                {"name": "order_id", "logicalType": "integer", "primaryKey": True},
                {
                    "name": "status",
                    "logicalType": "string",
                    "required": True,
                    "enum": [{"value": "open"}, {"value": "closed"}],
                },
            ],
            "quality": [{"metric": "rowCount", "mustBeGreaterThan": 10}],
        }
    ],
    "slaProperties": [{"property": "latency", "value": 4, "unit": "h", "element": "orders.ts"}],
}
v = odcs.validate_document(doc)
print("ok", v.api_version, v.schema_version, v.warnings)
for bad in ({**doc, "apiVersion": "v2.2.2"}, {**doc, "apiVersion": "v4.0.0"}):
    try:
        odcs.validate_document(bad)
    except Exception as exc:
        print(type(exc).__name__, str(exc)[:90])
v = odcs.validate_document({**doc, "apiVersion": "v3.3.0"})
print("newer", v.schema_version, v.warnings)
try:
    odcs.validate_document({**doc, "schema": [{"properties": []}]})
except Exception as exc:
    print(type(exc).__name__, str(exc)[:160], exc.detail)
v30 = odcs.validate_document(
    {
        "apiVersion": "v3.0.0",
        "kind": "DataContract",
        "id": "x",
        "version": "1",
        "status": "active",
        "schema": [
            {
                "name": "t",
                "quality": [{"type": "library", "rule": "duplicateCount", "mustBe": 0}],
            }
        ],
    }
)
print("v3.0.0 ok", v30.schema_version)

